33	export async function modeSetup(record: SessionRecord, ctx: ModeContext): Promise<ModeSetup> {
34	  const { workspaceRoot } = ctx
35	  // A chat may write a spec when asked to, held to the contract like the planner's.
36	  const chat = { hooks: new SpecContract(workspaceRoot) }
37	  if (record.access === 'full') return chat
38	  switch (record.mode) {
39	    case 'chat':
40	      return chat
41	    case 'implement': {
42	      if (!record.feature) throw new Error('An implement session needs a feature name')
43	      return {
44	        // The user's answers amend the task's rules, held to the contract like the planner's writes.
45	        hooks: composeHooks(new TaskBoardGuard(workspaceRoot, record.feature), new SpecContract(workspaceRoot)),
46	        systemPrompt: await ctx.withMap(record, implementPrompt(record.feature, workspaceRoot, ctx.verifyRules())),
47	        toolNames: IMPLEMENT_TOOLS,
48	      }
49	    }
50	    case 'plan': {
51	      if (!record.feature) throw new Error('A plan session needs a feature name')
52	      const scope = blindPlanScope(record.feature, ctx.planIgnore())
53	      return {
54	        // The contract answers on the write that broke it, so the planner fixes the spec in the same turn.
55	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
56	        systemPrompt: await ctx.withDocs(record, blindPlanPrompt(record.feature, workspaceRoot)),
57	        toolNames: BLIND_PLAN_TOOLS,
58	        readable: readableIn(scope),
59	      }
60	    }
61	    case 'code-plan':
62	      // Read-only by its tool set: nothing to scope, and the build happens once the plan is approved.
63	      return {
64	        systemPrompt: await ctx.withMap(record, await ctx.withDocs(record, codePlanPrompt(workspaceRoot))),
65	        toolNames: CODE_PLAN_TOOLS,
66	      }
67	    case 'docs': {
68	      const scope = docsEvaluationScope(ctx.planIgnore())
69	      return {
70	        hooks: new ScopeGuard(workspaceRoot, scope),
71	        systemPrompt: await ctx.withDocs(record, docsEvaluationPrompt(workspaceRoot)),
72	        toolNames: DOCS_EVALUATION_TOOLS,
73	        readable: readableIn(scope),
74	      }
75	    }
76	    case 'file-decisions': {
77	      const scope = fileDecisionsScope(ctx.planIgnore())
78	      return {
79	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
80	        systemPrompt: await ctx.withDocs(record, fileDecisionsPrompt(workspaceRoot)),
81	        toolNames: FILE_DECISIONS_TOOLS,
82	        readable: readableIn(scope),
83	      }
84	    }
85	    case 'docs-map': {
86	      return {
87	        // The entry contract answers on the write that broke it, so a bad anchor never reaches a planner's prompt.
88	        hooks: composeHooks(new ScopeGuard(workspaceRoot, docsMapScope(record.files ?? [])), new DocsMapContract(workspaceRoot)),
89	        systemPrompt: docsMapPrompt(workspaceRoot),
90	        toolNames: DOCS_MAP_TOOLS,
91	      }
92	    }
93	    case 'reconcile': {
94	      if (!record.feature) throw new Error('A reconcile session needs a feature name')
95	      return {
96	        hooks: composeHooks(
97	          new ScopeGuard(workspaceRoot, reconcileScope(record.feature)),
98	          new SpecContract(workspaceRoot),
99	          new ScenarioContextContract(workspaceRoot, record.feature),
100	        ),
101	        systemPrompt: await ctx.withMap(record, reconcilePrompt(record.feature, workspaceRoot)),
102	        toolNames: RECONCILE_TOOLS,
103	      }
104	    }
105	    case 'cleanup': {
106	      if (!record.feature || !record.files) throw new Error('A cleanup session needs a feature name and the files to split')
107	      return {
108	        hooks: new ScopeGuard(workspaceRoot, cleanupScope(record.files)),
109	        systemPrompt: cleanupPrompt(record.feature, workspaceRoot, ctx.cleanupLimits()),
110	        toolNames: CLEANUP_TOOLS,
111	      }
112	    }
113	  }
114	}
